module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg        clk;
    reg        reset;
    wire [31:0] q;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    // Clock generation: 10ns period
    initial begin
        clk = 0;
        forever #5 clk = ~clk;
    end

    // Reference model function for a single step of the Galois LFSR
    // Taps at 32, 22, 2, 1 (1-indexed), corresponding to indices 31, 21, 1, 0 in 0-indexed [31:0]
    // Polynomial: x^32 + x^22 + x^2 + x^1 + 1 (Mask: 80400003)
    function [31:0] lfsr_step;
        input [31:0] current_q;
        reg feedback;
        begin
            feedback = current_q[0];
            if (feedback)
                lfsr_step = (current_q >> 1) ^ 32'h80400003;
            else
                lfsr_step = (current_q >> 1);
        end
    endfunction

    integer errors = 0;
    integer i;
    reg [31:0] expected_q;

    // 3. Stimulus & self-checking
    initial begin
        // Initialize inputs
        reset = 1'b1;
        expected_q = 32'h00000001;

        // Apply reset for a couple of cycles
        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            errors = errors + 1;
        end

        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            errors = errors + 1;
        end

        // Release reset
        reset = 1'b0;

        // Check reset value immediately after deassertion on next edge
        @(posedge clk);
        #1;
        // At the first active clock after reset goes low, q should still be 1 before transition, 
        // or let's track expected state synchronously.

        // Let's run a bounded loop of 20 test vectors
        for (i = 0; i < 20; i = i + 1) begin
            // Compute expected for the next cycle
            expected_q = lfsr_step(expected_q);

            @(posedge clk);
            #1; // Wait slightly after posedge to sample stable output

            if (q !== expected_q) begin
                errors = errors + 1;
                $display("Mismatch at step %0d: got %h, expected %h", i, q, expected_q);
            end
        end

        // Test asynchronous/synchronous reset behavior mid-stream
        @(posedge clk);
        reset = 1'b1;
        expected_q = 32'h00000001;

        @(posedge clk);
        #1;
        if (q !== expected_q) begin
            errors = errors + 1;
        end

        reset = 1'b0;
        @(posedge clk);
        expected_q = lfsr_step(expected_q);
        #1;
        if (q !== expected_q) begin
            errors = errors + 1;
        end

        // Final result reporting
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end

        $finish;
    end

endmodule
